INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'castle', 'n.', '/ˈkɑːsl/', '城堡;堡垒', 'We visited an old castle on the hill.', '我们参观了山上一座古老的城堡。', 'Travelling Around', 1, 0, 'senior', 'wordlist', 'required1', 'U2', 'an old castle', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'apply', 'v.', '/əˈplaɪ/', '申请;请求;应用', 'You must apply for a visa before the trip.', '旅行前你必须申请签证。', 'Travelling Around', 2, 0, 'senior', 'wordlist', 'required1', 'U2', 'apply for a visa', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'visa', 'n.', '/ˈviːzə/', '签证', 'It took two weeks to get my visa.', '办我的签证花了两周。', 'Travelling Around', 3, 0, 'senior', 'wordlist', 'required1', 'U2', 'get a visa', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'rent', 'v./n.', '/rent/', '租用;出租;租金', 'We rented a car to explore the island.', '我们租了辆车去探索这座岛。', 'Travelling Around', 4, 0, 'senior', 'wordlist', 'required1', 'U2', 'rent a car', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'pack', 'v.', '/pæk/', '收拾(行李);包装', 'Don''t forget to pack your warm clothes.', '别忘了把保暖衣物装进行李。', 'Travelling Around', 5, 0, 'senior', 'wordlist', 'required1', 'U2', 'pack your bags', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'amazing', 'adj.', '/əˈmeɪzɪŋ/', '令人惊奇的;令人惊喜的', 'The mountains gave us an amazing view.', '群山给了我们令人惊叹的景色。', 'Travelling Around', 6, 0, 'senior', 'wordlist', 'required1', 'U2', 'an amazing view', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'amazed', 'adj.', '/əˈmeɪzd/', '惊奇的;惊喜的', 'I was amazed at the size of the old city.', '我对这座古城的规模感到惊讶。', 'Travelling Around', 7, 0, 'senior', 'wordlist', 'required1', 'U2', 'be amazed at', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'arrangement', 'n.', '/əˈreɪndʒmənt/', '安排;筹备', 'She made all the arrangements for the journey.', '她安排好了旅程的一切。', 'Travelling Around', 8, 0, 'senior', 'wordlist', 'required1', 'U2', 'make arrangements', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'extremely', 'adv.', '/ɪkˈstriːmli/', '极其;非常', 'The lake was extremely beautiful at sunrise.', '日出时湖面极其美丽。', 'Travelling Around', 9, 0, 'senior', 'wordlist', 'required1', 'U2', 'extremely beautiful', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'source', 'n.', '/sɔːs/', '来源;出处;水源', 'They walked to the source of the river.', '他们走到了这条河的源头。', 'Travelling Around', 10, 0, 'senior', 'wordlist', 'required1', 'U2', 'the source of a river', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'narrow', 'adj.', '/ˈnærəʊ/', '狭窄的', 'We climbed up a narrow mountain path.', '我们沿着一条狭窄的山路往上爬。', 'Travelling Around', 11, 0, 'senior', 'wordlist', 'required1', 'U2', 'a narrow path', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'flat', 'adj./n.', '/flæt/', '平坦的;公寓', 'After the hills, the road became flat.', '翻过山丘后,路变得平坦了。', 'Travelling Around', 12, 0, 'senior', 'wordlist', 'required1', 'U2', 'flat land', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'detail', 'n.', '/ˈdiːteɪl/', '细节;详情', 'The guide explained the history in detail.', '导游详细讲解了这段历史。', 'Travelling Around', 13, 0, 'senior', 'wordlist', 'required1', 'U2', 'in detail', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'powerful', 'adj.', '/ˈpaʊəfl/', '强大的;有影响力的', 'The Inca built a powerful empire long ago.', '很久以前印加人建立了一个强大的帝国。', 'Travelling Around', 14, 0, 'senior', 'wordlist', 'required1', 'U2', 'a powerful empire', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'empire', 'n.', '/ˈempaɪə(r)/', '帝国', 'Machu Picchu was part of the Inca Empire.', '马丘比丘曾是印加帝国的一部分。', 'Travelling Around', 15, 0, 'senior', 'wordlist', 'required1', 'U2', 'the Inca Empire', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'emperor', 'n.', '/ˈempərə(r)/', '皇帝', 'The city was built for a great emperor.', '这座城是为一位伟大的皇帝而建。', 'Travelling Around', 16, 0, 'senior', 'wordlist', 'required1', 'U2', 'a great emperor', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'site', 'n.', '/saɪt/', '地点;遗址;现场', 'This is a famous historical site in Peru.', '这是秘鲁一处著名的历史遗址。', 'Travelling Around', 17, 0, 'senior', 'wordlist', 'required1', 'U2', 'a historical site', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'view', 'n.', '/vjuː/', '视野;景色;看法', 'From the top we had a great view of the valley.', '从山顶我们看到了山谷的壮丽景色。', 'Travelling Around', 18, 0, 'senior', 'wordlist', 'required1', 'U2', 'a great view', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'sight', 'n.', '/saɪt/', '景象;视野;视力', 'We spent a day seeing the sights of the city.', '我们花了一天游览城市的景点。', 'Travelling Around', 19, 0, 'senior', 'wordlist', 'required1', 'U2', 'see the sights', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'official', 'adj./n.', '/əˈfɪʃl/', '官方的;官员', 'Spanish is the official language of Peru.', '西班牙语是秘鲁的官方语言。', 'Travelling Around', 20, 0, 'senior', 'wordlist', 'required1', 'U2', 'the official language', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'statue', 'n.', '/ˈstætʃuː/', '雕像;塑像', 'There is an old stone statue near the gate.', '门旁有一尊古老的石雕像。', 'Travelling Around', 21, 0, 'senior', 'wordlist', 'required1', 'U2', 'a stone statue', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'recognise', 'vt.', '/ˈrekəɡnaɪz/', '辨认出;承认;认可', 'I could hardly recognise the old town.', '我几乎认不出这座古镇了。', 'Travelling Around', 22, 0, 'senior', 'wordlist', 'required1', 'U2', 'recognise a place', '美式拼 recognize;美音 /ˈrekəɡnaɪz/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tomb', 'n.', '/tuːm/', '坟墓', 'Workers unearthed an ancient tomb here.', '工人在这里挖出了一座古墓。', 'Travelling Around', 23, 0, 'senior', 'wordlist', 'required1', 'U2', 'an ancient tomb', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'unearth', 'vt.', '/ʌnˈɜːθ/', '挖掘;发掘', 'Scientists unearthed a lost city in the jungle.', '科学家在丛林中发掘出一座失落的城市。', 'Travelling Around', 24, 0, 'senior', 'wordlist', 'required1', 'U2', 'unearth a city', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'type', 'n.', '/taɪp/', '类型;种类', 'This is a special type of mountain train.', '这是一种特别的山地火车。', 'Travelling Around', 25, 0, 'senior', 'wordlist', 'required1', 'U2', 'a type of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'comment', 'n./v.', '/ˈkɒment/', '评论;议论', 'Many tourists made comments about the view.', '许多游客对这景色发表了评论。', 'Travelling Around', 26, 0, 'senior', 'wordlist', 'required1', 'U2', 'make a comment', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'flight', 'n.', '/flaɪt/', '航班;空中航行', 'We booked an early flight to Peru.', '我们订了一班飞往秘鲁的早班机。', 'Travelling Around', 27, 0, 'senior', 'wordlist', 'required1', 'U2', 'book a flight', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'accommodation', 'n.', '/əˌkɒməˈdeɪʃn/', '住处;膳宿', 'We booked our accommodation online.', '我们在网上订好了住处。', 'Travelling Around', 28, 0, 'senior', 'wordlist', 'required1', 'U2', 'book accommodation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'unique', 'adj.', '/juˈniːk/', '独特的;唯一的', 'Each old city has its own unique culture.', '每座古城都有自己独特的文化。', 'Travelling Around', 29, 0, 'senior', 'wordlist', 'required1', 'U2', 'a unique culture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'path', 'n.', '/pɑːθ/', '小路;路线', 'The path led us up to the temple.', '这条小路带我们爬到了神庙。', 'Travelling Around', 30, 0, 'senior', 'wordlist', 'required1', 'U2', 'a mountain path', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'destination', 'n.', '/ˌdestɪˈneɪʃn/', '目的地;终点', 'Peru is a popular destination for hikers.', '秘鲁是徒步者热门的目的地。', 'Travelling Around', 31, 0, 'senior', 'wordlist', 'required1', 'U2', 'a popular destination', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'admire', 'vt.', '/ədˈmaɪə(r)/', '钦佩;赞赏;欣赏', 'We stopped to admire the beautiful view.', '我们停下来欣赏美丽的景色。', 'Travelling Around', 32, 0, 'senior', 'wordlist', 'required1', 'U2', 'admire the view', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'architecture', 'n.', '/ˈɑːkɪtektʃə(r)/', '建筑设计;建筑学', 'Tourists love the ancient architecture here.', '游客们喜爱这里的古建筑。', 'Travelling Around', 33, 0, 'senior', 'wordlist', 'required1', 'U2', 'ancient architecture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'architect', 'n.', '/ˈɑːkɪtekt/', '建筑设计师', 'A famous architect designed the bridge.', '一位著名建筑师设计了这座桥。', 'Travelling Around', 34, 0, 'senior', 'wordlist', 'required1', 'U2', 'a famous architect', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'brochure', 'n.', '/ˈbrəʊʃə(r)/', '(介绍信息的)小册子', 'She picked up a travel brochure at the airport.', '她在机场拿了一本旅行手册。', 'Travelling Around', 35, 0, 'senior', 'wordlist', 'required1', 'U2', 'a travel brochure', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'soldier', 'n.', '/ˈsəʊldʒə(r)/', '士兵;军人', 'The old fort once kept many soldiers.', '这座古堡曾驻扎过许多士兵。', 'Travelling Around', 36, 0, 'senior', 'wordlist', 'required1', 'U2', 'a brave soldier', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'transport', 'n./vt.', '/ˈtrænspɔːt/', '交通运输;运送', 'Public transport in the city is cheap and fast.', '这座城市的公共交通又便宜又快。', 'Travelling Around', 37, 0, 'senior', 'wordlist', 'required1', 'U2', 'public transport', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'hike', 'v./n.', '/haɪk/', '徒步旅行;远足', 'We went for a long hike in the mountains.', '我们到山里进行了一次长途徒步。', 'Travelling Around', 38, 0, 'senior', 'wordlist', 'required1', 'U2', 'go for a hike', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'economy', 'n.', '/ɪˈkɒnəmi/', '经济;节约', 'Tourism is important to the local economy.', '旅游业对当地经济很重要。', 'Travelling Around', 39, 0, 'senior', 'wordlist', 'required1', 'U2', 'the local economy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'economic', 'adj.', '/ˌiːkəˈnɒmɪk/', '经济(上)的;经济学的', 'Travel brings economic growth to small towns.', '旅游给小城镇带来经济增长。', 'Travelling Around', 40, 0, 'senior', 'wordlist', 'required1', 'U2', 'economic growth', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'request', 'n./vt.', '/rɪˈkwest/', '(礼貌的)要求;请求', 'I made a request for a room with a view.', '我请求要一间有景观的房间。', 'Travelling Around', 41, 0, 'senior', 'wordlist', 'required1', 'U2', 'make a request', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u2.01', '①be going to(计划打算 + 有迹象的预测)', 'A2', 10, '必修一 U2 — be going to do 表示已定的计划/打算,或根据现有迹象作出的预测(Look at the clouds! It is going to rain.)。', 1, 'required1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u2.02', '②will(将来 / 临时决定 / 预测)', 'A2', 10, '必修一 U2 — will do 表示对将来的预测、说话当下做出的临时决定、承诺或主动提议(I will help you.)。', 2, 'required1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u2.03', '③现在进行时表将来(已确定的安排)', 'A2', 10, '必修一 U2 — be doing 表示按计划/时间表已确定、近期就要发生的安排,常带将来时间状语(We are leaving tomorrow.)。', 3, 'required1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U2' AND code='u2.01'), '"Look at those dark clouds! It ____ rain soon."', 'is going to', 'was', 'rained', 'rains', 'A', '有迹象(乌云)→ be going to 预测,主语 it 用 is going to。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U2' AND code='u2.01'), '"We ____ visit Peru next summer; we''ve already booked the flight."', 'went', 'are going to', 'visit', 'were going', 'B', '已定计划 → be going to,主语 we 用 are going to。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U2' AND code='u2.01'), '"She ____ apply for a visa tomorrow."', 'was', 'applied', 'is going to', 'applies', 'C', '打算做的事 → is going to apply。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U2' AND code='u2.01'), '"Be careful! That box ____ fall."', 'fell', 'falls', 'was going', 'is going to', 'D', '看到迹象作预测 → is going to fall。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U2' AND code='u2.01'), '"They ____ rent a car for the trip."', 'are not going to', 'did not', 'are not', 'were not going', 'A', '计划的否定 → are not going to rent。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U2' AND code='u2.01'), '"____ you going to pack tonight?"', 'Do', 'Are', 'Did', 'Will', 'B', 'be going to 一般疑问,主语 you → Are you going to。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U2' AND code='u2.01'), '"I ____ hike to Machu Picchu; I''ve planned it for months."', 'was', 'hiked', 'am going to', 'hike', 'C', '长期计划 → am going to hike。', 2, 7, 'mcq');
