INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U2' AND code='u2.03'), '"____ you flying or driving to the coast next week?"', 'Do', 'Did', 'Are', 'Were', 'C', '问已定方式 → Are you flying…?', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U2' AND code='u2.03'), '"The plane ____ off in half an hour, so board now."', 'take', 'took', 'was taking', 'is taking', 'D', '近期已定 → is taking off。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Explore Peru', 'Peru is a country in South America with a rich history and amazing sights. Many travellers come here to explore the Inca Empire, which was once powerful and ruled a large area. The most famous site is Machu Picchu, a lost city high in the Andes Mountains. It was built for an emperor about 600 years ago and was unearthed only a hundred years ago. Today visitors can hike along a narrow mountain path to reach it and admire its unique stone architecture. Other than Machu Picchu, Peru also has deep rainforests and the source of the Amazon River. The official language is Spanish, but many people still speak older languages too. Whatever your interest, Peru is an unforgettable destination.', '说明·探索秘鲁', 120, '[{"q":"Why do many travellers visit Peru?","answer":"A","options":["To explore its history and amazing sights.","To learn to speak French.","To buy cheap cars.","To watch football matches."],"explanation":"原文 rich history and amazing sights … explore the Inca Empire 的概括。"},{"q":"What is Machu Picchu?","answer":"B","options":["A modern airport in Lima.","An ancient city high in the mountains.","A large shopping centre.","A river in the rainforest."],"explanation":"原文 a lost city high in the Andes 的转述,非照抄。"},{"q":"How can visitors reach Machu Picchu today?","answer":"C","options":["By taking a boat across the sea.","By driving on a wide flat road.","By walking up a narrow mountain path.","By flying directly to the city centre."],"explanation":"原文 hike along a narrow mountain path 的转述。"},{"q":"What else does Peru have besides Machu Picchu?","answer":"D","options":["Deserts with no water.","Only modern buildings.","No old languages at all.","Thick rainforests and the beginning of the Amazon River."],"explanation":"原文 rainforests and the source of the Amazon River(考后半段,覆盖不同位置)。"}]'::jsonb, '[{"word":"empire","cn":"帝国"},{"word":"site","cn":"遗址;地点"},{"word":"destination","cn":"目的地"}]'::jsonb, 2, 'required1', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Getting Ready for a Trip', 'Travelling to another country is exciting, but good planning makes it easier. First, decide on your destination and find out whether you need a visa. Some countries ask travellers to apply for one weeks before they arrive, so do not leave it too late. Next, book your flight and accommodation early, because prices often rise as the date comes near. It is also wise to read about the local culture and learn a few words of the language. Make a list of what to pack, and keep your tickets and passport in a safe place. Finally, plan your daily activities, but leave some free time too. With careful arrangements made in advance, you can relax and enjoy every moment of your journey.', '说明·行前规划', 122, '[{"q":"What is the first thing the writer suggests doing?","answer":"A","options":["Choosing where to go and checking visa rules.","Buying lots of gifts.","Packing all your clothes.","Learning to drive."],"explanation":"原文 decide on your destination and find out whether you need a visa 的概括。"},{"q":"Why should you book flights and rooms early?","answer":"B","options":["Because they are always free.","Because prices tend to go up later.","Because airports close at night.","Because hotels dislike late guests."],"explanation":"原文 prices often rise as the date comes near 的转述。"},{"q":"What does the writer advise about your daily plan?","answer":"C","options":["Fill every hour with activities.","Never make any plan.","Leave some free time as well.","Only rest in the hotel."],"explanation":"原文 leave some free time too(考后半段)。"},{"q":"What is the main idea of the passage?","answer":"D","options":["Travelling is too much trouble.","You should travel alone.","Visas are a waste of money.","Careful planning makes a trip easier and more enjoyable."],"explanation":"全文主旨:good planning makes it easier。"}]'::jsonb, '[{"word":"visa","cn":"签证"},{"word":"accommodation","cn":"住宿"},{"word":"arrangement","cn":"安排"}]'::jsonb, 2, 'required1', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Hike to Remember', 'Last summer my family went hiking in the mountains. We got up before sunrise and started along a narrow path through the forest. At first the walk was easy, but soon the path became steep and our bags felt extremely heavy. My little brother wanted to give up, so I carried his bag for a while. After three hours we reached the top, and the view there made everyone forget how tired they were. Below us we could see a silver river and green valleys stretching far away. We sat down to rest and admire the scenery, and Dad took many photos. The way down was much easier, and by evening we were back at our small hotel, tired but happy. It was the best day of the whole trip.', '记叙·山中徒步', 130, '[{"q":"When did the family begin their hike?","answer":"A","options":["Early, before the sun rose.","Late at night.","At lunchtime.","In the evening."],"explanation":"原文 before sunrise 的转述。"},{"q":"Why did the writer carry the brother''s bag?","answer":"B","options":["The bag was empty.","The brother was tired and wanted to stop.","The writer liked heavy bags.","Dad asked for it."],"explanation":"原文 my little brother wanted to give up 的转述。"},{"q":"How did everyone feel at the top?","answer":"C","options":["Bored and angry.","Too tired to look.","Amazed by the view and no longer tired.","Afraid of the height."],"explanation":"原文 the view … made everyone forget how tired they were(考中段)。"},{"q":"How does the writer describe the day overall?","answer":"D","options":["A waste of time.","A frightening day.","A boring day.","The finest day of the whole journey."],"explanation":"原文 the best day of the whole trip(考结尾)。"}]'::jsonb, '[{"word":"narrow","cn":"狭窄的"},{"word":"admire","cn":"欣赏;钦佩"},{"word":"steep","cn":"陡峭的"}]'::jsonb, 2, 'required1', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Ways to Get Around', 'When you travel, choosing the right transport can save both time and money. For long distances, flying is the fastest way, though tickets can be expensive. Trains are slower but let you enjoy the changing scenery through the window, and they often reach the city centre directly. In many cities, public transport such as buses and the underground is cheap and easy to use. If you want freedom, you can rent a car and stop wherever you like, but remember that parking is sometimes hard to find. For short trips, walking or cycling is healthy and lets you see small streets that buses pass by. The best choice depends on your time, your money and the kind of experience you are looking for.', '说明·出行方式', 123, '[{"q":"According to the passage, what is the fastest way to travel far?","answer":"A","options":["Flying.","Cycling.","Walking.","Taking a bus."],"explanation":"原文 flying is the fastest way 的转述。"},{"q":"What advantage of trains does the writer mention?","answer":"B","options":["They are always free.","You can enjoy the scenery and reach the city centre.","They never stop.","They are the cheapest of all."],"explanation":"原文 enjoy the changing scenery … reach the city centre directly。"},{"q":"What problem of renting a car is mentioned?","answer":"C","options":["Cars cannot turn.","Cars are too slow.","Parking can be hard to find.","You cannot stop anywhere."],"explanation":"原文 parking is sometimes hard to find(考中段)。"},{"q":"What does the writer say about the best choice of transport?","answer":"D","options":["It is always the plane.","It is always walking.","It never matters.","It depends on time, money and the experience you want."],"explanation":"原文结尾 depends on your time, your money and the kind of experience。"}]'::jsonb, '[{"word":"transport","cn":"交通运输"},{"word":"rent","cn":"租用"},{"word":"view","cn":"景色;看法"}]'::jsonb, 2, 'required1', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Castle in the Mountains', 'High in the mountains of southern Germany stands a beautiful castle that looks like something from a fairy tale. It was built for a king who loved music and stories, and its tall white towers can be seen from far away. Visitors today walk up a path to reach the gate, just as people did long ago. Inside, the rooms are full of wonderful paintings and unique furniture, and from the windows you can admire an amazing view of green valleys and a blue lake. The castle was never quite finished, because the king died before the work was complete. Even so, it has become one of the most popular destinations in the country, and millions of tourists come to see its famous architecture every year.', '说明·山中城堡', 126, '[{"q":"Who was the castle built for?","answer":"A","options":["A music-loving king who enjoyed stories.","A soldier.","A famous architect.","A group of farmers."],"explanation":"原文 built for a king who loved music and stories 的转述。"},{"q":"What can visitors see from the castle windows?","answer":"B","options":["A busy modern city.","Open valleys and a lake far below.","A wide flat desert.","Nothing at all."],"explanation":"原文 admire an amazing view of green valleys and a blue lake。"},{"q":"Why was the castle never quite finished?","answer":"C","options":["It ran out of stone.","Tourists stopped the work.","Its king passed away before it was finished.","It was too cold."],"explanation":"原文 the king died before the work was complete(考后半段)。"},{"q":"How popular is the castle today?","answer":"D","options":["Almost no one visits.","Only kings may enter.","It is closed forever.","Millions of tourists come each year."],"explanation":"原文 millions of tourists come … every year(考结尾)。"}]'::jsonb, '[{"word":"castle","cn":"城堡"},{"word":"architecture","cn":"建筑"},{"word":"unique","cn":"独特的"}]'::jsonb, 2, 'required1', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Why We Travel', 'People travel for many different reasons. Some go abroad to relax and escape their busy lives, while others want excitement and adventure. Travelling also teaches us a great deal. When we visit new places, we meet people whose lives are different from our own, and we begin to understand the world better. We taste new food, hear new languages and see how others solve everyday problems. Such experiences can change the way we think. Of course, travelling is not always easy: flights may be delayed and plans may go wrong. But even the difficult moments often become the stories we enjoy telling later. In the end, the greatest gift of travel is not the photos we bring home, but the way it opens our minds.', '议论·为何旅行', 125, '[{"q":"According to the passage, why do some people travel?","answer":"A","options":["To relax or to look for adventure.","To stay at home.","To avoid all new food.","To stop learning."],"explanation":"原文 relax and escape … others want excitement and adventure 的概括。"},{"q":"What does the writer say travelling teaches us?","answer":"B","options":["Nothing useful.","To understand the world and other people better.","To dislike strangers.","Only how to take photos."],"explanation":"原文 understand the world better … see how others solve problems。"},{"q":"What does the writer say about difficult moments?","answer":"C","options":["They ruin every trip.","They never happen.","They often become enjoyable stories later.","They should be forgotten at once."],"explanation":"原文 become the stories we enjoy telling later(考后半段)。"},{"q":"What does the writer think is the greatest gift of travel?","answer":"D","options":["The photos we bring home.","The money we spend.","The food we eat.","How it broadens the way we think."],"explanation":"原文结尾 not the photos … but the way it opens our minds。"}]'::jsonb, '[{"word":"culture","cn":"文化"},{"word":"experience","cn":"经历;经验"},{"word":"admire","cn":"欣赏"}]'::jsonb, 2, 'required1', 'U2');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U2', 'A Postcard from Peru', 'Dear Mum, I am having a wonderful time in Peru! Yesterday we (1)____ up early and took a train to Machu Picchu. The (2)____ from the mountain was amazing — green valleys everywhere. We walked along a (3)____ path to reach the old city, and our guide explained its history in (4)____. I was (5)____ at how the Inca built such a place so long ago. Today we are going to (6)____ the local market and buy some gifts. The food here is (7)____ and the people are very friendly. The only problem is that my bag is too (8)____ to carry! Tomorrow we (9)____ flying to the rainforest, so I will send you more photos. I really hope you can come here one (10)____. Love, Anna', 127, 2, '[{"q":"1","answer":"A","options":["got","lost","gave","sold"],"explanation":"got up early 早起。"},{"q":"2","answer":"B","options":["noise","view","smell","price"],"explanation":"the view from the mountain 山上的景色。"},{"q":"3","answer":"C","options":["wide","flat","narrow","modern"],"explanation":"a narrow path 狭窄的小路。"},{"q":"4","answer":"D","options":["silence","danger","money","detail"],"explanation":"in detail 详细地。"},{"q":"5","answer":"A","options":["amazed","bored","angry","afraid"],"explanation":"be amazed at 对……惊叹。"},{"q":"6","answer":"B","options":["forget","explore","lose","close"],"explanation":"explore the market 逛市场。"},{"q":"7","answer":"C","options":["terrible","boring","delicious","empty"],"explanation":"food is delicious 食物美味。"},{"q":"8","answer":"D","options":["light","cheap","clean","heavy"],"explanation":"too heavy to carry 太重提不动。"},{"q":"9","answer":"A","options":["are","were","did","have"],"explanation":"are flying 现在进行时表将来。"},{"q":"10","answer":"B","options":["hour","day","week","minute"],"explanation":"one day 有一天。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U2', 'At the Airport', 'When you arrive at the airport, the first thing to do is to (1)____ in for your flight. Show your passport and ticket to the (2)____ at the desk, and put your big bag on the machine to be weighed. If your bag is too (3)____, you may have to pay extra. After that, you keep only a small bag and walk to the (4)____ gate shown on your ticket. Remember to (5)____ your boarding pass safe, because you will need it again. There is usually time to buy a drink or read a (6)____ before the plane is ready. When your flight is (7)____, you join the line and get on board. Soon the plane will (8)____ off and your journey begins. Flying can feel long, so it is a good idea to (9)____ a book or some music. Before you know it, you will (10)____ at your destination.', 150, 2, '[{"q":"1","answer":"C","options":["give","wake","check","turn"],"explanation":"check in 办理登机。"},{"q":"2","answer":"D","options":["driver","doctor","farmer","officer"],"explanation":"the officer at the desk 柜台工作人员。"},{"q":"3","answer":"A","options":["heavy","light","small","cheap"],"explanation":"too heavy 超重。"},{"q":"4","answer":"B","options":["wrong","right","old","free"],"explanation":"the right gate 正确的登机口。"},{"q":"5","answer":"C","options":["lose","throw","keep","sell"],"explanation":"keep … safe 妥善保管。"},{"q":"6","answer":"D","options":["mountain","machine","message","magazine"],"explanation":"read a magazine 看杂志。"},{"q":"7","answer":"A","options":["called","closed","broken","lost"],"explanation":"flight is called 航班开始登机。"},{"q":"8","answer":"B","options":["put","take","look","give"],"explanation":"take off 起飞。"},{"q":"9","answer":"C","options":["leave","lose","bring","drop"],"explanation":"bring a book 带本书。"},{"q":"10","answer":"D","options":["leave","return","stay","arrive"],"explanation":"arrive at your destination 到达目的地。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U2', 'Booking a Hotel', 'Finding good (1)____ is an important part of any trip. These days most people book a hotel (2)____ before they leave home. First, choose a place that is close to the sights you want to (3)____. Then read the comments that other travellers have (4)____, because they tell you what the rooms are really like. Check the (5)____ carefully, as some hotels look cheap but add extra fees. It is also wise to ask for a room with a nice (6)____, especially in the mountains. When you arrive, you check (7)____ at the front desk and show your booking. If you have any special (8)____, such as a quiet room, tell the staff politely. A friendly hotel can make your stay much more (9)____. When you leave, do not forget to check (10)____ and return your key.', 137, 2, '[{"q":"1","answer":"A","options":["accommodation","homework","weather","traffic"],"explanation":"find accommodation 找住处。"},{"q":"2","answer":"B","options":["outside","online","alone","loudly"],"explanation":"book online 网上预订。"},{"q":"3","answer":"C","options":["forget","lose","visit","sell"],"explanation":"sights you want to visit 想去的景点。"},{"q":"4","answer":"D","options":["lost","broken","eaten","left"],"explanation":"comments others have left 别人留下的评论。"},{"q":"5","answer":"A","options":["price","weather","noise","speed"],"explanation":"check the price 看价格。"},{"q":"6","answer":"B","options":["rule","view","test","job"],"explanation":"a room with a nice view 有好景观的房间。"},{"q":"7","answer":"C","options":["out","off","in","up"],"explanation":"check in 入住登记。"},{"q":"8","answer":"D","options":["mistakes","problems","answers","requests"],"explanation":"special requests 特别要求。"},{"q":"9","answer":"A","options":["pleasant","boring","dangerous","difficult"],"explanation":"more pleasant 更愉快。"},{"q":"10","answer":"B","options":["in","out","up","on"],"explanation":"check out 退房。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U2', 'A Day in a New City', 'There is no better way to know a city than to (1)____ around on foot. On our first morning, we left the hotel early and followed a small (2)____ into the old town. The streets were (3)____, with tall buildings on both sides, and every corner had something new to (4)____. We stopped to (5)____ the beautiful old architecture and take photos. Around noon we were hungry, so we tried a (6)____ kind of local food at a tiny restaurant. In the afternoon we used the city''s cheap public (7)____ to reach a famous museum. A guide there told us many interesting (8)____ about the city''s history. By evening our feet were tired, but we had (9)____ so much in just one day. We agreed that walking had shown us the (10)____ city far better than any bus tour.', 139, 2, '[{"q":"1","answer":"C","options":["lose","give","get","sell"],"explanation":"get around 四处走动。"},{"q":"2","answer":"D","options":["rule","test","team","path"],"explanation":"a small path 一条小路。"},{"q":"3","answer":"A","options":["narrow","wide","empty","modern"],"explanation":"streets were narrow 街道狭窄。"},{"q":"4","answer":"B","options":["hide","see","lose","close"],"explanation":"something new to see 新东西可看。"},{"q":"5","answer":"C","options":["break","forget","admire","throw"],"explanation":"admire the architecture 欣赏建筑。"},{"q":"6","answer":"D","options":["boring","terrible","empty","special"],"explanation":"a special kind of food 一种特别的食物。"},{"q":"7","answer":"A","options":["transport","homework","weather","money"],"explanation":"public transport 公共交通。"},{"q":"8","answer":"B","options":["mistakes","details","problems","rules"],"explanation":"interesting details 有趣的细节。"},{"q":"9","answer":"C","options":["lost","missed","seen","broken"],"explanation":"had seen so much 看了那么多。"},{"q":"10","answer":"D","options":["fake","empty","false","real"],"explanation":"the real city 真实的城市。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U2', 'Learning About a Culture', 'Travelling to another country is a great way to learn about a different (1)____. Before you go, it helps to read a little about the local way of (2)____. Try to learn a few (3)____ in the local language, such as "hello" and "thank you"; people are always pleased when visitors make the (4)____. Remember that what is polite at home may be (5)____ somewhere else, so watch how local people behave and follow their (6)____. Be ready to taste food that looks (7)____ to you — it is often delicious. Most importantly, keep an open (8)____ and treat everyone with respect. If you are friendly and (9)____, local people will be happy to help you. In this way, a journey can do more than show you new places; it can also help you (10)____ the world better.', 138, 2, '[{"q":"1","answer":"A","options":["culture","machine","weather","price"],"explanation":"a different culture 不同的文化。"},{"q":"2","answer":"B","options":["money","life","noise","speed"],"explanation":"the way of life 生活方式。"},{"q":"3","answer":"C","options":["cars","rooms","words","rules"],"explanation":"learn a few words 学几个词。"},{"q":"4","answer":"D","options":["mistake","noise","money","effort"],"explanation":"make the effort 努力尝试。"},{"q":"5","answer":"A","options":["rude","kind","happy","easy"],"explanation":"polite at home may be rude elsewhere 别处可能失礼。"},{"q":"6","answer":"B","options":["machine","example","ticket","price"],"explanation":"follow their example 学他们的样子。"},{"q":"7","answer":"C","options":["normal","boring","strange","empty"],"explanation":"food that looks strange 看起来陌生的食物。"},{"q":"8","answer":"D","options":["door","box","book","mind"],"explanation":"keep an open mind 保持开放心态。"},{"q":"9","answer":"A","options":["polite","rude","lazy","angry"],"explanation":"friendly and polite 友好礼貌。"},{"q":"10","answer":"B","options":["forget","understand","leave","lose"],"explanation":"understand the world better 更好理解世界。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U2', 'How to Pack Well', 'Packing the right way can make a journey much (1)____. Many travellers take far too much and end up with a bag that is too (2)____ to carry. The trick is to make a (3)____ of what you really need before you start. Choose clothes that are easy to wash and can be (4)____ for different days. Always keep your passport, tickets and some money in a (5)____ place that you can reach quickly. Pack a small bag for the things you will need during the (6)____, such as a book and a bottle of water. Do not (7)____ to leave a little space for the gifts you may buy. It is also wise to bring any medicine you might (8)____. Finally, check your list once more so that you do not (9)____ anything important. With good packing, you can (10)____ your trip instead of worrying about your bags.', 149, 2, '[{"q":"1","answer":"C","options":["harder","longer","easier","slower"],"explanation":"much easier 容易得多。"},{"q":"2","answer":"D","options":["light","cheap","clean","heavy"],"explanation":"too heavy to carry 太重。"},{"q":"3","answer":"A","options":["list","noise","price","rule"],"explanation":"make a list 列清单。"},{"q":"4","answer":"B","options":["lost","worn","sold","broken"],"explanation":"can be worn for different days 可换着穿。"},{"q":"5","answer":"C","options":["busy","loud","safe","far"],"explanation":"a safe place 安全的地方。"},{"q":"6","answer":"D","options":["school","class","game","flight"],"explanation":"during the flight 飞行途中。"},{"q":"7","answer":"A","options":["forget","agree","refuse","promise"],"explanation":"don''t forget 别忘了。"},{"q":"8","answer":"B","options":["lose","need","sell","hide"],"explanation":"medicine you might need 可能需要的药。"},{"q":"9","answer":"C","options":["win","keep","miss","open"],"explanation":"do not miss anything 不漏掉东西。"},{"q":"10","answer":"D","options":["hate","stop","lose","enjoy"],"explanation":"enjoy your trip 享受旅行。"}]'::jsonb, 6);
