INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'WU 听力·短文 My Trip to Peru', '必修一 U2 · passage', 2, 'Last summer I visited Peru with my family.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'WU 听力·对话 Checking In at the Hotel', '必修一 U2 · dialogue', 3, 'Guest: Hello, I have a booking under the name Green.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'WU 听力·短文 Why I Love Hiking', '必修一 U2 · passage', 2, 'My favourite way to travel is hiking.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'WU 听力·对话 Asking for Directions', '必修一 U2 · dialogue', 3, 'Visitor: Excuse me, how can I get to the old castle?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'WU 听力·短文 A Tip for Travellers', '必修一 U2 · passage', 2, 'Here is a simple tip for anyone who loves travelling.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write to a Friend About a Travel Experience(给朋友写一次旅行经历)', 'A Travel Email', '假设你叫李华,暑假和家人去了一个地方旅行。请用英语给你的朋友 Sam 写一封电子邮件(约80词),分享这次旅行,内容包括:① 你去了哪里、怎么去的;② 在那里做了什么、看到了什么;③ 你的感受;④ 邀请对方下次一起去。', 'Suppose you are Li Hua. You travelled somewhere with your family during the summer holiday. Write an email (about 80 words) to your friend Sam to share the trip, including: 1) where you went and how you got there; 2) what you did and saw; 3) how you felt; 4) an invitation to go together next time.', '["去哪里 + 怎么去(I went to … We got there by …)","做了什么 + 看到什么(We visited … / We saw …)","感受(It was amazing / I''ll never forget …)","邀请(I hope we can go together next time.)"]'::jsonb, 70, 100, 'Dear Sam,
